import { spawn } from "node:child_process";
const args = process.argv.slice(2); const value = (flag) => args[args.indexOf(flag) + 1]; const mode = value("--mode") ?? "success"; const task = value("--task") ?? ""; const success = (response = `echo: ${task}`) => process.stdout.write(JSON.stringify({ status: "success", response, modelReported: "fake-1", cwd: process.cwd() }));
if (mode === "warning") { process.stderr.write("warning\n"); success(); } else if (mode === "invalid-json") process.stdout.write("{"); else if (mode === "exit-nonzero") { process.stderr.write("failed\n"); process.exitCode = 3; } else if (mode === "empty") {} else if (mode === "overflow") process.stdout.write("x".repeat(1024 * 1024)); else if (mode === "hang") setInterval(() => {}, 1000); else if (mode === "grandchild") { spawn(process.execPath, ["-e", "setInterval(()=>{},1000)"], { stdio: "ignore" }); setInterval(() => {}, 1000); } else if (mode === "unicode") success("Tiếng Việt có dấu: ă â đ ê ô ơ ư"); else if (mode === "echo-cwd") success(process.cwd()); else success();